routine.definition:
DECLARE
  v_history_table TEXT;
  v_pk_column TEXT;
BEGIN
  v_history_table := TG_ARGV[0];
  v_pk_column := TG_ARGV[1];

  -- For INSERT and UPDATE, enforce audit fields
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    NEW.updated_at := now();
    NEW.updated_by := COALESCE(current_setting('app.current_user', true), current_user);
    IF TG_OP = 'INSERT' THEN
      NEW.created_at := now();
      NEW.created_by := COALESCE(current_setting('app.current_user', true), current_user);
    ELSE
      NEW.created_at := OLD.created_at;
      NEW.created_by := OLD.created_by;
    END IF;
  END IF;

  -- Capture to history (AFTER trigger instead)
  EXECUTE format(
    'INSERT INTO notify.%I (target_row_id, operation_type, operation_user,
     operation_executed_at, data_after_operation) VALUES ($1.%I, %L, %L, now(), to_jsonb($1))',
    v_history_table, v_pk_column, SUBSTRING(TG_OP, 1, 1),
    COALESCE(current_setting('app.current_user', true), current_user)
  ) USING NEW;

  RETURN NEW;
END;

BEGIN -- Only create a new version if the template content or metadata has actually changed IF (OLD.subject IS DISTINCT FROM NEW.subject OR OLD.body IS DISTINCT FROM NEW.body OR OLD.engine_code IS DISTINCT FROM NEW.engine_code OR OLD.channel_code IS DISTINCT FROM NEW.channel_code OR OLD.name IS DISTINCT FROM NEW.name OR OLD.description IS DISTINCT FROM NEW.description) THEN
-- Get the next version number NEW.version := COALESCE(( SELECT MAX(version) + 1 FROM notify.template_version WHERE template_id = NEW.id ), 1);
-- Insert version record INSERT INTO notify.template_version ( id, template_id, version, name, description, channel_code, subject, body, engine_code, created_by, created_at ) VALUES ( gen_random_uuid(), NEW.id, NEW.version, NEW.name, NEW.description, NEW.channel_code, NEW.subject, NEW.body, NEW.engine_code, COALESCE(NEW.updated_by, 'system'), NOW() ); END IF;
RETURN NEW; END;

BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
